// spec: .qa/e2e/specs/journey.md
// seed: tests/seed.user1.spec.ts
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

async function counters(page: Page) {
  const out: Record<string, string> = {};
  for (const name of ['ימים רצופים', 'תפילות היום', 'סה״כ תפילות']) {
    const region = page.getByRole('region', { name: new RegExp(`^${name}: \\d+$`) });
    await expect(region).toBeVisible({ timeout: 20_000 });
    out[name] = ((await region.getAttribute('aria-label')) ?? '').split(': ')[1];
  }
  return out;
}

test.describe('«המסע שלי»', () => {
  test('JR-01 «המסע שלי» на реальных данных — уровень, счётчики = главная, פילוח, последние молитвы, מפת השפעה, достижения #6a86f7e8 @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page); // окно уровня «עלית דרגה» не должно перекрывать экран
    // 1. Открыть `/home`, запомнить 3 счётчика.
    await page.goto('/home');
    const home = await counters(page);

    // 2. Открыть `/journey`.
    await page.goto('/journey');
    await expect(page.getByRole('heading', { level: 1, name: 'המסע שלי' })).toBeVisible({ timeout: 20_000 });
    await dismissMilestoneIfShown(page);
    await expect(page.getByText('מסור', { exact: true })).toBeVisible();
    await expect(page.getByText('זו הדרגה הגבוהה ביותר')).toBeVisible();
    await expect(page.getByText('דרגה 10 מתוך 10')).toBeVisible();

    const journey = await counters(page);
    expect(journey).toEqual(home);

    await expect(page.getByRole('button', { name: /^מקבל על עצמי/ })).toBeVisible();

    // «פילוח תפילות»: שחרית + מנחה + ערבית = «סה״כ תפילות»
    await expect(page.getByRole('heading', { name: 'פילוח תפילות' })).toBeVisible();
    let sum = 0;
    for (const name of ['שחרית', 'מנחה', 'ערבית']) {
      const region = page.getByRole('region', { name: new RegExp(`^${name}: \\d+$`) });
      await expect(region).toBeVisible();
      sum += Number(((await region.getAttribute('aria-label')) ?? '').split(': ')[1]);
    }
    expect(sum).toBe(Number(journey['סה״כ תפילות']));

    // «מפת השפעה»
    await expect(page.getByRole('heading', { name: 'מפת השפעה' })).toBeVisible();
    await expect(page.getByText('2 אנשים')).toBeVisible();
    await expect(page.getByRole('button', { name: 'הזמנת אדם להתחזק' })).toBeVisible();

    // «הישגים» — 6 штук
    await expect(page.getByRole('heading', { name: 'הישגים' })).toBeVisible();
    for (const n of ['תפילה ראשונה', 'שבוע שלם', 'חודש רצוף']) {
      await expect(page.getByText(n, { exact: true })).toHaveCount(1);
    }
    await expect(page.getByLabel(/: (הושג|טרם הושג)$/)).toHaveCount(6);

    // Нет горизонтальной прокрутки
    expect(await page.evaluate(() => document.documentElement.scrollWidth <= document.documentElement.clientWidth)).toBe(true);

    // 3. Нажать «צפה בהכל».
    await expect(page.getByText('תפילות אחרונות', { exact: true })).toBeVisible();
    await page.getByRole('link', { name: 'צפה בהכל' }).click();
    await expect(page).toHaveURL(/\/journey\/history$/);
  });
});
